# ------------------------------------------------------------ 80 Insinyur Lingkungan
# Sumber yang dibaca: deskripsi pekerjaan Environmental Engineer dari 4 Corner Resources (agen perekrutan Amerika) dan profil karier
# Environmental Engineer dari ECO Canada (lembaga sumber daya manusia sektor lingkungan Kanada). Keduanya luar negeri. Halaman 4 Corner
# tidak menyebut persyaratan pendidikan formal; ECO Canada menyebut umumnya gelar sarjana. Bagi siswa SMK, ini tujuan jangka panjang
# lewat pendidikan sarjana. Kursus tidak menyuruh siswa menyentuh limbah atau bahan kimia berbahaya. Tidak ada klaim gaji.
kursus(80, "Insinyur Lingkungan",
 bab(["Menjelaskan apa yang dikerjakan insinyur lingkungan dengan bahasa sederhana.",
      "Menyebut tugas utama menurut dua sumber.",
      "Menjelaskan bahwa ini tujuan jangka panjang lewat pendidikan sarjana.",
      "Menyebut catatan jujur tentang sumber."],
  ("Pekerjaan insinyur lingkungan",
   "4 Corner Resources menyebut insinyur lingkungan merancang sistem dan komponen untuk mengurangi dampak negatif terhadap lingkungan, menangani masalah pencemaran, pengelolaan limbah, dan kualitas udara, serta meneliti dampak lingkungan suatu proyek. Bayangkan insinyur lingkungan sebagai dokter bagi lingkungan: ia memeriksa tanda-tanda pencemaran, mencari penyebabnya, dan merancang penyembuhannya."),
  ("Tugas utama",
   "4 Corner menyebut melakukan pemeriksaan kendali mutu agar kebijakan dan standar lingkungan terpenuhi, menyusun laporan, rekomendasi, dan dokumentasi, serta sebagian menjadi penasihat teknis untuk kepatuhan regulasi. ECO Canada menyebut menilai apakah lokasi industri memenuhi kriteria kualitas lingkungan, merancang rencana pengelolaan limbah, memantau operasi agar patuh, merekomendasikan prosedur pembersihan lokasi tercemar, serta menulis dan mengevaluasi laporan dampak lingkungan."),
  ("Tujuan jangka panjang",
   "ECO Canada menyebut persyaratan minimum umumnya gelar sarjana, dengan program yang paling relevan Teknik Lingkungan, Teknik Sipil, Teknik Kimia, dan Teknik Mesin, serta minat pada matematika, fisika, kimia, dan biologi. Halaman 4 Corner tidak menyebut pendidikan formal secara eksplisit. Bagi siswa SMK ini tujuan jangka panjang lewat pendidikan sarjana."),
  ("Catatan jujur tentang sumber",
   "4 Corner adalah agen perekrutan Amerika dan ECO Canada adalah lembaga sumber daya manusia sektor lingkungan Kanada. Keduanya berkonteks luar negeri, sehingga lisensi, sertifikasi, dan regulasinya tidak otomatis berlaku di Indonesia. Kursus ini tidak membahas gaji dan tidak mengajarkan penanganan limbah.")),
 bab(["Menjelaskan jenis masalah lingkungan yang ditangani.",
      "Menjelaskan dampak lingkungan dan laporan.",
      "Menjelaskan kepatuhan pada regulasi.",
      "Menjelaskan keselamatan terhadap bahan berbahaya."],
  ("Jenis masalah lingkungan",
   "4 Corner menyebut pencemaran, pengelolaan limbah, dan kualitas udara, dan ECO Canada menyebut penanganan, minimisasi, pengolahan, dan pembuangan limbah untuk pemerintah dan industri. Contoh umum: sampah yang menumpuk, air sungai yang berubah warna, atau asap pabrik, yang masing-masing perlu diukur dulu sebelum dicari solusinya."),
  ("Dampak lingkungan dan laporan",
   "4 Corner menyebut meneliti dampak lingkungan suatu proyek dan menganalisis datanya, dan ECO Canada menyebut menulis dan mengevaluasi laporan dampak lingkungan. Praktik umum: laporan harus jujur dan didukung data, karena keputusan tentang proyek besar dapat bergantung padanya."),
  ("Kepatuhan pada regulasi",
   "4 Corner menyebut pemahaman menyeluruh terhadap peraturan, regulasi, dan praktik terbaik lingkungan, dan ECO Canada menyebut memantau operasi agar tetap patuh pada regulasi lingkungan. Regulasi dalam sumber adalah regulasi luar negeri, sehingga aturan Indonesia harus dipelajari dari sumber resmi dan guru."),
  ("Keselamatan terhadap bahan berbahaya",
   "ECO Canada menyebut merekomendasikan prosedur pembersihan lokasi yang tercemar bahan berbahaya, dan 4 Corner menyebut familiaritas dengan peralatan teknik dan keselamatan kerja. Praktik umum: limbah dan bahan kimia dapat membahayakan kesehatan, sehingga siswa tidak boleh menyentuh, mengambil sampel, atau membuang limbah berbahaya tanpa pelatihan dan pengawasan.")),
 bab(["Menyebut keterampilan yang disebut sumber.",
      "Menjelaskan pendidikan secara hati-hati.",
      "Menjelaskan dasar yang bisa dilatih siswa SMK.",
      "Menjelaskan keterbatasan sumber."],
  ("Keterampilan",
   "4 Corner menyebut pengetahuan prinsip teknik, ilmu tanah, biologi, dan kimia, kemampuan berkolaborasi dengan ilmuwan dan perencana, komunikasi lisan dan tulisan, kemahiran perangkat lunak analisis seperti SAS atau AutoCAD, serta kemampuan melihat gambaran besar. ECO Canada menyebut Microsoft Office, bahasa pemrograman, desain dan analisis sistem, pemodelan data, manajemen proses, kerja tim, kepemimpinan, dan pemecahan masalah."),
  ("Pendidikan",
   "ECO Canada menyebut gelar sarjana dan program Teknik Lingkungan, Sipil, Kimia, atau Mesin, serta sertifikasi Certified Environmental Professional sebagai nilai tambah, tanpa lisensi wajib. Itu gambaran Kanada. Tanyakan ke guru tentang program studi dan sertifikasi di Indonesia, dan ingat jalurnya melalui pendidikan sarjana."),
  ("Dasar untuk siswa SMK",
   "Praktik umum: belajar matematika, kimia, dan biologi dasar, belajar Excel untuk mengolah data, mengamati dan mencatat kondisi lingkungan sekolah tanpa menyentuh limbah berbahaya, dan menulis laporan sederhana. Siswa jurusan kimia, pertanian, atau teknik sipil sudah mengenal sebagian dasar ini."),
  ("Keterbatasan sumber",
   "Sumber tidak menjelaskan cara menganalisis pencemaran, tidak membahas aturan lingkungan Indonesia seperti analisis dampak lingkungan, dan 4 Corner tidak menyebut pendidikan. Jangan mengambil sampel limbah atau air tercemar sendiri tanpa pelatihan.")),
 bab(["Menjelaskan kebiasaan kerja yang baik.",
      "Menjelaskan mencari pengalaman yang aman.",
      "Menyusun rencana belajar bagi siswa.",
      "Menyusun portofolio untuk peran ini."],
  ("Kebiasaan kerja",
   "Praktik umum: ukur dulu sebelum menyimpulkan, catat sumber data, tulis asumsi, dan bedakan fakta dari dugaan. Laporan yang jujur menyebut ketidakpastian, dan data tidak boleh disesuaikan agar hasilnya tampak bagus."),
  ("Mencari pengalaman yang aman",
   "Praktik umum: ikut kegiatan Adiwiyata atau bank sampah sekolah dengan izin guru, lakukan survei sampah di sekolah dengan sarung tangan dan pengawasan, dan tanya dinas lingkungan atau lembaga lokal tentang kegiatan relawan. Jangan menyentuh limbah kimia atau sampah medis."),
  ("Rencana belajar",
   "Bulan pertama: pelajari jenis masalah lingkungan dan istilah dasar. Bulan kedua: lakukan survei sampah sekolah selama satu minggu dan catat di Excel. Bulan ketiga: analisis data, tulis rekomendasi pengurangan sampah, dan minta guru memeriksa. Ini saran praktik umum."),
  ("Portofolio",
   "Portofolio memuat data survei sampah, grafik, laporan dan rekomendasi, serta ringkasan masalah lingkungan di sekolah. Jangan memuat foto limbah berbahaya atau data pribadi orang.")),
 bab(["Menjelaskan etika dan kejujuran data.",
      "Menjelaskan terus belajar.",
      "Menjelaskan jalur belajar lanjut secara hati-hati.",
      "Menyebut langkah berikutnya bagi siswa."],
  ("Etika dan kejujuran data",
   "4 Corner menyebut komunikasi tertulis dan dokumentasi, dan ECO Canada menyebut mengevaluasi laporan dampak lingkungan. Praktik umum: laporan lingkungan memengaruhi kesehatan banyak orang, sehingga data tidak boleh dipalsukan dan konflik kepentingan harus diakui."),
  ("Terus belajar",
   "4 Corner menyebut kemahiran perangkat lunak dan pemahaman praktik terbaik lingkungan. Praktik umum: peraturan dan teknologi lingkungan berubah, sehingga pantau sumber resmi dan literatur terbaru."),
  ("Jalur belajar lanjut",
   "ECO Canada menyebut program Teknik Lingkungan, Sipil, Kimia, atau Mesin, dan menyebut sertifikasi sebagai nilai tambah. Tanyakan ke guru dan alumni tentang program studi, beasiswa, dan peluang yang realistis di Indonesia."),
  ("Langkah berikutnya",
   "Langkah nyata: lakukan survei sampah sederhana selama satu minggu di sekolah, tulis rekomendasi, dan minta guru memeriksa. Ini saran praktik umum.")),
 {"title": "Proyek: Survei Sampah Sekolah dan Rekomendasi Pengurangan",
  "brief": "Dengan izin guru, lakukan survei sampah di satu area sekolah selama lima hari. Catat jenis sampah, misalnya plastik, kertas, dan sisa makanan, dan perkiraan jumlahnya per hari di Excel, tanpa menyentuh sampah dengan tangan telanjang dan tanpa mengambil limbah berbahaya. Buat grafik jenis sampah terbanyak. Tulis laporan satu halaman berisi tujuan, metode, hasil, keterbatasan, dan tiga rekomendasi pengurangan sampah yang masuk akal. Tulis bagian ketidakpastian dengan jujur. Tidak boleh memuat foto limbah berbahaya atau data pribadi orang.",
  "criteria": ["Data survei lima hari tercatat rapi di Excel",
               "Grafik jenis sampah benar dan mudah dibaca",
               "Laporan memuat tujuan, metode, hasil, dan keterbatasan",
               "Tiga rekomendasi masuk akal dan didukung data",
               "Bagian ketidakpastian ditulis jujur dan keselamatan dijaga",
               "Dokumen diunggah ke GitHub atau folder portofolio tanpa data pribadi"]},
 banks([2, 0, 1, 3], [
  (2, "A", "Apa pekerjaan insinyur lingkungan secara sederhana?", "Merancang sistem untuk mengurangi dampak negatif terhadap lingkungan", ["Menjual perabot sepanjang tahun berjalan di seluruh bagian organisasi pada setiap akhir periode kerja", "Mengajar olahraga", "Memasak"], "4 Corner menggambarkan pekerjaan tersebut."),
  (2, "A", "Apa analogi insinyur lingkungan di kursus ini?", "Dokter bagi lingkungan yang mencari penyebab dan merancang penyembuhan", ["Penjual tiket tanpa terkecuali sama sekali sepanjang tahun berjalan di seluruh bagian organisasi", "Penjaga parkir", "Pencuci piring"], "Analogi untuk memahami peran."),
  (2, "K", "Pendidikan umum apa yang ECO Canada sebut?", "Gelar sarjana", ["Hanya SD", "Hanya kursus sehari", "Tidak ada"], "ECO Canada menyebut umumnya gelar sarjana."),
  (2, "K", "Apa yang 4 Corner sebut tentang pendidikan?", "Tidak menyebut persyaratan pendidikan formal secara eksplisit", ["Wajib doktor pada setiap akhir periode kerja tanpa terkecuali sama sekali", "Melarang sekolah", "Hanya lulusan SD"], "Halaman 4 Corner tidak menyebut pendidikan."),
  (2, "K", "Apa catatan jujur tentang dua sumber?", "Keduanya luar negeri sehingga lisensi dan regulasinya tidak otomatis berlaku di Indonesia", ["Keduanya dari Indonesia sepanjang tahun berjalan di seluruh bagian organisasi pada setiap akhir periode kerja", "Keduanya tanpa konteks", "Keduanya putusan pengadilan"], "4 Corner Amerika dan ECO Canada Kanada."),
  (2, "A", "Mengapa gaji tidak dibahas?", "Karena sumber luar negeri dan tidak mewakili Indonesia", ["Karena tidak digaji tanpa terkecuali sama sekali sepanjang tahun berjalan", "Karena rahasia negara", "Karena selalu sama"], "Kursus tidak memuat klaim gaji."),
  (2, "K", "Mengapa ini tujuan jangka panjang bagi siswa SMK?", "Karena umumnya memerlukan pendidikan sarjana", ["Karena tidak ada pendidikan di seluruh bagian organisasi", "Karena SMK dilarang", "Karena otomatis lulus"], "ECO Canada menyebut gelar sarjana."),
  (3, "A", "Masalah apa yang 4 Corner sebut?", "Pencemaran, pengelolaan limbah, dan kualitas udara", ["Hanya jalan rusak pada setiap akhir periode kerja tanpa terkecuali sama sekali", "Hanya harga barang", "Tidak ada"], "4 Corner menyebut ketiga masalah tersebut."),
  (3, "A", "Apa yang ECO Canada sebut tentang laporan?", "Menulis dan mengevaluasi laporan dampak lingkungan", ["Tidak ada laporan sepanjang tahun berjalan di seluruh bagian organisasi", "Hanya menyanyi", "Hanya menjual"], "ECO Canada menyebut laporan dampak lingkungan."),
  (3, "K", "Mengapa laporan lingkungan harus jujur dan didukung data?", "Karena keputusan proyek dan kesehatan banyak orang dapat bergantung padanya", ["Karena tidak ada pengaruh pada setiap akhir periode kerja tanpa terkecuali sama sekali", "Karena hanya hiasan", "Karena tidak dibaca"], "Praktik umum etika laporan."),
  (3, "K", "Mengapa aturan Indonesia dipelajari dari sumber resmi?", "Karena regulasi dalam sumber adalah regulasi luar negeri", ["Karena aturan sama di semua negara sepanjang tahun berjalan", "Karena aturan dilarang", "Karena tidak ada aturan"], "Sumber berkonteks luar negeri."),
  (3, "K", "Apa yang tidak boleh dilakukan siswa terhadap limbah berbahaya?", "Menyentuh, mengambil sampel, atau membuangnya tanpa pelatihan dan pengawasan", ["Menggambarnya di seluruh bagian organisasi pada setiap akhir periode kerja tanpa terkecuali sama sekali", "Membaca tentangnya", "Mencatat istilahnya"], "Limbah dan bahan kimia dapat membahayakan kesehatan."),
  (3, "A", "Mengapa mengukur dulu sebelum mencari solusi?", "Karena solusi harus berdasarkan data", ["Karena data tidak penting", "Karena menebak lebih cepat sepanjang tahun berjalan", "Karena tidak ada solusi"], "Praktik umum kerja berbasis data."),
  (3, "K", "Apa yang ECO Canada sebut tentang lokasi tercemar?", "Merekomendasikan prosedur pembersihan lokasi yang tercemar bahan berbahaya", ["Mengabaikan lokasi di seluruh bagian organisasi pada setiap akhir periode kerja", "Menutupnya diam-diam", "Menjualnya"], "ECO Canada menyebut prosedur pembersihan."),
  (4, "A", "Keterampilan apa yang 4 Corner sebut?", "Pengetahuan teknik, ilmu tanah, biologi, kimia, dan komunikasi", ["Hanya menari tanpa terkecuali sama sekali sepanjang tahun berjalan", "Hanya melukis", "Hanya menyanyi"], "4 Corner menyebut keterampilan tersebut."),
  (4, "A", "Program apa yang paling relevan menurut ECO Canada?", "Teknik Lingkungan, Teknik Sipil, Teknik Kimia, dan Teknik Mesin", ["Seni rupa di seluruh bagian organisasi pada setiap akhir periode kerja", "Tata boga", "Olahraga"], "ECO Canada menyebut program tersebut."),
  (4, "K", "Sertifikasi apa yang ECO Canada sebut sebagai nilai tambah?", "Certified Environmental Professional", ["Sertifikat memasak tanpa terkecuali sama sekali", "Sertifikat menari", "Tidak ada"], "ECO Canada menyebut sertifikasi tersebut sebagai nilai tambah."),
  (4, "K", "Bagaimana siswa berlatih dengan aman?", "Survei sampah sekolah dengan izin guru dan perlindungan tanpa menyentuh limbah berbahaya", ["Mengambil limbah kimia", "Mengambil sampel air tercemar sendiri", "Membuang limbah sembarangan"], "Saran praktik umum latihan aman."),
  (4, "K", "Apa yang tidak dibahas sumber?", "Aturan lingkungan Indonesia dan cara menganalisis pencemaran", ["Bahwa ada pencemaran", "Bahwa ada limbah", "Bahwa ada insinyur"], "Sumber tidak merinci hal tersebut."),
  (4, "A", "Jurusan SMK apa yang dekat dengan dasar ini?", "Kimia, pertanian, atau teknik sipil", ["Hanya tata busana", "Hanya seni musik", "Tidak ada"], "Dasar kimia, biologi, dan teknik dikenal di jurusan tersebut."),
  (4, "K", "Siapa yang bisa ditanya tentang jalur di Indonesia?", "Guru dan alumni", ["Hanya iklan", "Tidak ada", "Orang asing"], "Sumber luar negeri sehingga perlu dicek ke sumber resmi."),
  (5, "A", "Apa yang dilakukan sebelum menyimpulkan?", "Mengukur dan mencatat data serta asumsi", ["Menebak", "Menyalin kesimpulan", "Mengabaikan data"], "Praktik umum kerja berbasis data."),
  (5, "A", "Di mana siswa bisa mendapat pengalaman aman?", "Kegiatan Adiwiyata atau bank sampah sekolah dengan izin guru", ["Mengambil limbah kimia", "Menyentuh sampah medis", "Menunggu tanpa berusaha"], "Saran praktik umum pengalaman."),
  (5, "K", "Apa yang dilakukan dengan data yang hasilnya tidak sesuai harapan?", "Melaporkannya apa adanya", ["Mengubahnya", "Menyembunyikannya", "Menghapusnya"], "Praktik umum kejujuran data."),
  (5, "K", "Apa isi portofolio yang baik?", "Data survei, grafik, laporan, dan rekomendasi", ["Foto limbah berbahaya", "Data pribadi orang", "Janji lulus"], "Saran praktik umum portofolio."),
  (5, "A", "Apa yang 4 Corner sebut tentang komunikasi?", "Komunikasi lisan dan tulisan yang baik", ["Tidak perlu berkomunikasi", "Hanya diam", "Hanya menyanyi"], "4 Corner menyebut komunikasi lisan dan tulisan."),
  (5, "K", "Mengapa data tidak boleh disesuaikan agar tampak bagus?", "Karena laporan memengaruhi kesehatan dan keputusan banyak orang", ["Karena data tidak penting", "Karena tidak ada akibat", "Karena tidak dibaca"], "Praktik umum etika laporan."),
  (5, "K", "Apa yang dilakukan tentang regulasi dan program studi di Indonesia?", "Menanyakan ke guru dan sumber resmi", ["Mengabaikan", "Menebak", "Menganggap sama dengan luar negeri"], "Sumber luar negeri sehingga perlu dicek ke sumber resmi."),
 ]),
 sumber=[("4 Corner Resources: Environmental Engineer Job Description (agen perekrutan Amerika; tidak menyebut pendidikan formal)", "https://www.4cornerresources.com/job-descriptions/environmental-engineer"),
         ("ECO Canada: Environmental Engineer, career profile (lembaga sumber daya manusia sektor lingkungan Kanada)", "https://eco.ca/career-profiles/environmental-engineer/")])
